import{_ as t,o as i,c as s,ae as o}from"./chunks/framework.RRduUuAx.js";const u=JSON.parse('{"title":"Watchdog Scheduler and Three Detectors","description":"","frontmatter":{"work_package_id":"WP01","title":"Watchdog Scheduler and Three Detectors","lane":"done","dependencies":[],"base_branch":"main","base_commit":"c36745c15926bc46d62710af10aa4ca1718575b1","created_at":"2026-03-01T13:29:36.317013+00:00","subtasks":["T001","T002","T003","T004","T005","T006"],"phase":"Phase 1 - Detection Foundation","assignee":"","agent":"claude-haiku","shell_pid":"54633","review_status":"approved","reviewed_by":"Koosha Paridehpour","history":[{"timestamp":"2026-02-27T00:00:00Z","lane":"planned","agent":"system","shell_pid":"","action":"Prompt generated via /spec-kitty.tasks"}]},"headers":[],"relativePath":"specs/015-lane-orphan-detection-and-remediation/tasks/WP01-watchdog-scheduler-and-detectors.md","filePath":"specs/015-lane-orphan-detection-and-remediation/tasks/WP01-watchdog-scheduler-and-detectors.md"}'),a={name:"specs/015-lane-orphan-detection-and-remediation/tasks/WP01-watchdog-scheduler-and-detectors.md"};function r(l,e,c,n,d,p){return i(),s("div",null,[...e[0]||(e[0]=[o('<h1 id="work-package-prompt-wp01-watchdog-scheduler-and-three-detectors" tabindex="-1">Work Package Prompt: WP01 - Watchdog Scheduler and Three Detectors <a class="header-anchor" href="#work-package-prompt-wp01-watchdog-scheduler-and-three-detectors" aria-label="Permalink to &quot;Work Package Prompt: WP01 - Watchdog Scheduler and Three Detectors&quot;">​</a></h1><h2 id="objectives-success-criteria" tabindex="-1">Objectives &amp; Success Criteria <a class="header-anchor" href="#objectives-success-criteria" aria-label="Permalink to &quot;Objectives &amp; Success Criteria&quot;">​</a></h2><ul><li>Implement a periodic watchdog that runs orphan detection cycles at a configurable interval.</li><li>Implement three specialized detectors: orphaned worktree, stale zellij session, and leaked PTY process.</li><li>Implement resource classification with type, age, estimated owning lane, and risk level.</li><li>Implement checkpoint persistence for crash recovery.</li></ul><p>Success criteria:</p><ul><li>100% of intentionally orphaned resources are detected within two watchdog cycles.</li><li>Zero false positives on a healthy system with all lanes active.</li><li>Detection cycle completes in under 2 seconds for 100 lanes.</li><li>After simulated crash, watchdog resumes from the last checkpoint.</li></ul><h2 id="context-constraints" tabindex="-1">Context &amp; Constraints <a class="header-anchor" href="#context-constraints" aria-label="Permalink to &quot;Context &amp; Constraints&quot;">​</a></h2><ul><li>Constitution: <code>docs/reference/constitution.md</code></li><li>Plan: <code>/Users/kooshapari/CodeProjects/Phenotype/repos/heliosApp/kitty-specs/015-lane-orphan-detection-and-remediation/plan.md</code></li><li>Spec: <code>/Users/kooshapari/CodeProjects/Phenotype/repos/heliosApp/kitty-specs/015-lane-orphan-detection-and-remediation/spec.md</code></li><li>Lane lifecycle: spec 008</li><li>Session lifecycle: spec 009</li><li>Filesystem APIs for worktree enumeration</li><li>Process-table APIs for PTY process enumeration</li><li>zellij CLI for session listing</li></ul><p>Constraints:</p><ul><li>Watchdog must not consume more than 1% CPU on average during idle.</li><li>Detection only; no automatic cleanup (remediation is WP02).</li><li>Keep files under 500 lines.</li><li>TypeScript + Bun runtime.</li></ul><p>Implementation command:</p><ul><li><code>spec-kitty implement WP01</code></li></ul><h2 id="subtasks-detailed-guidance" tabindex="-1">Subtasks &amp; Detailed Guidance <a class="header-anchor" href="#subtasks-detailed-guidance" aria-label="Permalink to &quot;Subtasks &amp; Detailed Guidance&quot;">​</a></h2><h3 id="subtask-t001-implement-watchdog-scheduler-with-checkpoint-persistence" tabindex="-1">Subtask T001 - Implement watchdog scheduler with checkpoint persistence <a class="header-anchor" href="#subtask-t001-implement-watchdog-scheduler-with-checkpoint-persistence" aria-label="Permalink to &quot;Subtask T001 - Implement watchdog scheduler with checkpoint persistence&quot;">​</a></h3><ul><li>Purpose: run periodic detection cycles and persist state for crash recovery.</li><li>Steps: <ol><li>Implement <code>OrphanWatchdog</code> in <code>apps/runtime/src/lanes/watchdog/orphan_watchdog.ts</code>: a. Accept configurable <code>detectionInterval</code> (default: 60 seconds). b. Implement <code>start()</code> to begin the periodic detection loop using <code>setInterval</code> or <code>setTimeout</code> chain. c. Implement <code>stop()</code> to cleanly halt the loop. d. On each cycle: run all three detectors, collect results, classify resources, store results. e. After each cycle: update checkpoint with cycle timestamp and summary.</li><li>Implement <code>WatchdogCheckpoint</code> in <code>apps/runtime/src/lanes/watchdog/checkpoint.ts</code>: a. Persist: last cycle timestamp, cycle number, detected orphan count, detection results summary. b. Storage: file-backed JSON at <code>~/.helios/data/watchdog_checkpoint.json</code>. c. <code>save(checkpoint)</code>: write to disk. d. <code>load(): WatchdogCheckpoint | null</code>: read from disk; return null if missing or corrupt.</li><li>Implement crash recovery: a. On <code>start()</code>, load checkpoint. If present, log resume information and continue from last cycle number. b. If checkpoint is corrupt or missing, start fresh with cycle 0.</li><li>Implement CPU-awareness: measure cycle duration and log warnings if cycles exceed 2 seconds.</li><li>Export the watchdog class for lifecycle management.</li></ol></li><li>Files: <ul><li><code>/Users/kooshapari/CodeProjects/Phenotype/repos/heliosApp/apps/runtime/src/lanes/watchdog/orphan_watchdog.ts</code></li><li><code>/Users/kooshapari/CodeProjects/Phenotype/repos/heliosApp/apps/runtime/src/lanes/watchdog/checkpoint.ts</code></li></ul></li><li>Validation: <ul><li>Unit test: start watchdog with short interval (100ms), verify detection cycles run.</li><li>Unit test: stop watchdog, verify no further cycles.</li><li>Unit test: save checkpoint, reload, assert values match.</li><li>Unit test: simulate corrupt checkpoint file, assert fresh start.</li></ul></li><li>Parallel: No.</li></ul><h3 id="subtask-t002-implement-orphaned-worktree-detector" tabindex="-1">Subtask T002 - Implement orphaned worktree detector <a class="header-anchor" href="#subtask-t002-implement-orphaned-worktree-detector" aria-label="Permalink to &quot;Subtask T002 - Implement orphaned worktree detector&quot;">​</a></h3><ul><li>Purpose: detect git worktrees on disk that have no corresponding active lane in the registry.</li><li>Steps: <ol><li>Implement <code>WorktreeDetector</code> in <code>apps/runtime/src/lanes/watchdog/worktree_detector.ts</code>: a. Accept a worktree base directory path and a lane registry query interface as dependencies. b. <code>detect(): OrphanedResource[]</code>: i. Enumerate all git worktrees under the base directory (use <code>git worktree list --porcelain</code> or filesystem scan). ii. For each worktree, extract its lane identifier (from directory naming convention or metadata file). iii. Cross-reference against the lane registry: if no active lane matches, classify as orphaned. iv. Record: worktree path, detected lane ID (if determinable), creation time (from filesystem), age.</li><li>Handle edge cases: a. Worktree with no identifiable lane: classify as orphaned with <code>unknown</code> owning lane. b. Worktree whose lane is in <code>cleaning</code> state: do NOT classify as orphaned (transient state). c. Worktree whose lane is in <code>recovering</code> state: do NOT classify as orphaned.</li><li>Return structured <code>OrphanedResource</code> objects with type <code>worktree</code>.</li></ol></li><li>Files: <ul><li><code>/Users/kooshapari/CodeProjects/Phenotype/repos/heliosApp/apps/runtime/src/lanes/watchdog/worktree_detector.ts</code></li></ul></li><li>Validation: <ul><li>Unit test: mock filesystem with 3 worktrees (2 active, 1 orphaned), verify only orphan detected.</li><li>Unit test: worktree with lane in <code>cleaning</code> state, verify NOT detected as orphan.</li><li>Unit test: worktree with no identifiable lane, verify detected with <code>unknown</code> owner.</li></ul></li><li>Parallel: No.</li></ul><h3 id="subtask-t003-implement-stale-zellij-session-detector" tabindex="-1">Subtask T003 - Implement stale zellij session detector <a class="header-anchor" href="#subtask-t003-implement-stale-zellij-session-detector" aria-label="Permalink to &quot;Subtask T003 - Implement stale zellij session detector&quot;">​</a></h3><ul><li>Purpose: detect zellij sessions that have no corresponding active lane or session binding.</li><li>Steps: <ol><li>Implement <code>ZellijDetector</code> in <code>apps/runtime/src/lanes/watchdog/zellij_detector.ts</code>: a. Accept a session registry query interface as dependency. b. <code>detect(): OrphanedResource[]</code>: i. List all zellij sessions (use <code>zellij list-sessions</code> CLI or equivalent API). ii. Parse session names/IDs to extract lane/session identifiers. iii. Cross-reference against the session registry: if no active session matches, classify as stale. iv. Record: zellij session name, detected session/lane ID, creation time, age.</li><li>Handle edge cases: a. Zellij session with unrecognizable name: classify as orphaned with <code>unknown</code> owner. b. Zellij session whose lane is recovering: do NOT classify as orphaned.</li><li>Return structured <code>OrphanedResource</code> objects with type <code>zellij_session</code>.</li></ol></li><li>Files: <ul><li><code>/Users/kooshapari/CodeProjects/Phenotype/repos/heliosApp/apps/runtime/src/lanes/watchdog/zellij_detector.ts</code></li></ul></li><li>Validation: <ul><li>Unit test: mock zellij session list with 2 active + 1 stale, verify only stale detected.</li><li>Unit test: zellij session with recovering lane, verify NOT detected.</li><li>Unit test: unrecognizable session name, verify detected with <code>unknown</code> owner.</li></ul></li><li>Parallel: No.</li></ul><h3 id="subtask-t004-implement-leaked-pty-process-detector" tabindex="-1">Subtask T004 - Implement leaked PTY process detector <a class="header-anchor" href="#subtask-t004-implement-leaked-pty-process-detector" aria-label="Permalink to &quot;Subtask T004 - Implement leaked PTY process detector&quot;">​</a></h3><ul><li>Purpose: detect PTY-attached processes that have no parent lane or session ownership.</li><li>Steps: <ol><li>Implement <code>PtyDetector</code> in <code>apps/runtime/src/lanes/watchdog/pty_detector.ts</code>: a. Accept a terminal registry query interface as dependency. b. <code>detect(): OrphanedResource[]</code>: i. Enumerate PTY-attached processes (use platform-specific APIs: <code>ps</code> command with PTY filter on macOS/Linux). ii. For each PTY process, determine its PID and associated terminal. iii. Cross-reference against the terminal registry: if no terminal binding exists for this PTY, classify as leaked. iv. Record: PID, PTY device, detected terminal/lane ID, process age.</li><li>Handle edge cases: a. System PTY processes (not owned by Helios): filter by known process group or parent PID chain. b. PTY processes that were just spawned (within last 5 seconds): skip to avoid race conditions.</li><li>Return structured <code>OrphanedResource</code> objects with type <code>pty_process</code>.</li></ol></li><li>Files: <ul><li><code>/Users/kooshapari/CodeProjects/Phenotype/repos/heliosApp/apps/runtime/src/lanes/watchdog/pty_detector.ts</code></li></ul></li><li>Validation: <ul><li>Unit test: mock process table with 3 PTY processes (2 bound, 1 leaked), verify only leaked detected.</li><li>Unit test: system PTY process not owned by Helios, verify NOT detected.</li><li>Unit test: recently spawned PTY (&lt; 5s), verify NOT detected (grace period).</li></ul></li><li>Parallel: No.</li></ul><h3 id="subtask-t005-implement-resource-classifier" tabindex="-1">Subtask T005 - Implement resource classifier <a class="header-anchor" href="#subtask-t005-implement-resource-classifier" aria-label="Permalink to &quot;Subtask T005 - Implement resource classifier&quot;">​</a></h3><ul><li>Purpose: classify each orphaned resource by type, age, estimated owning lane, and risk level.</li><li>Steps: <ol><li>Implement <code>ResourceClassifier</code> in <code>apps/runtime/src/lanes/watchdog/resource_classifier.ts</code>: a. Accept an <code>OrphanedResource</code> and produce a <code>ClassifiedOrphan</code>: i. <code>type</code>: <code>worktree</code> | <code>zellij_session</code> | <code>pty_process</code>. ii. <code>age</code>: duration since resource creation (from filesystem/process metadata). iii. <code>estimatedOwner</code>: lane ID if determinable, <code>unknown</code> otherwise. iv. <code>riskLevel</code>: <code>low</code> (age &lt; 1 hour, known owner) | <code>medium</code> (age 1-24 hours) | <code>high</code> (age &gt; 24 hours or unknown owner). b. Risk level calculation should consider both age and ownership confidence.</li><li>Implement classification summary: a. <code>classifyAll(resources: OrphanedResource[]): ClassifiedOrphan[]</code>. b. Sort by risk level (high first) for presentation.</li><li>Export types and classifier for use by remediation (WP02) and UI.</li></ol></li><li>Files: <ul><li><code>/Users/kooshapari/CodeProjects/Phenotype/repos/heliosApp/apps/runtime/src/lanes/watchdog/resource_classifier.ts</code></li></ul></li><li>Validation: <ul><li>Unit test: classify resource aged 30 minutes with known owner, assert <code>low</code> risk.</li><li>Unit test: classify resource aged 12 hours with known owner, assert <code>medium</code> risk.</li><li>Unit test: classify resource aged 2 days with unknown owner, assert <code>high</code> risk.</li><li>Unit test: classifyAll sorts by risk level descending.</li></ul></li><li>Parallel: No.</li></ul><h3 id="subtask-t006-add-unit-tests-for-detectors-classifier-and-checkpoint" tabindex="-1">Subtask T006 - Add unit tests for detectors, classifier, and checkpoint <a class="header-anchor" href="#subtask-t006-add-unit-tests-for-detectors-classifier-and-checkpoint" aria-label="Permalink to &quot;Subtask T006 - Add unit tests for detectors, classifier, and checkpoint&quot;">​</a></h3><ul><li>Purpose: lock detection behavior and validate false-positive rate.</li><li>Steps: <ol><li>Create <code>apps/runtime/tests/unit/lanes/watchdog/orphan_watchdog.test.ts</code>: a. Test scheduler starts, runs cycles, stops cleanly. b. Test checkpoint save/load/corrupt recovery.</li><li>Create <code>apps/runtime/tests/unit/lanes/watchdog/worktree_detector.test.ts</code>: a. Test detection with mixed active/orphaned worktrees. b. Test transient state exclusion (cleaning, recovering). c. Test unknown owner classification.</li><li>Create <code>apps/runtime/tests/unit/lanes/watchdog/zellij_detector.test.ts</code>: a. Test detection with mixed active/stale sessions. b. Test recovery-aware exclusion.</li><li>Create <code>apps/runtime/tests/unit/lanes/watchdog/pty_detector.test.ts</code>: a. Test detection with mixed bound/leaked processes. b. Test system process filtering. c. Test grace period for recently spawned processes.</li><li>Create <code>apps/runtime/tests/unit/lanes/watchdog/resource_classifier.test.ts</code>: a. Test risk level calculations across age/owner combinations. b. Test sorting behavior.</li><li>False-positive validation: a. Create a healthy system mock with all resources bound. b. Run all detectors 100 times and assert zero false positives.</li><li>Aim for &gt;=90% line coverage on watchdog modules.</li></ol></li><li>Files: <ul><li><code>/Users/kooshapari/CodeProjects/Phenotype/repos/heliosApp/apps/runtime/tests/unit/lanes/watchdog/orphan_watchdog.test.ts</code></li><li><code>/Users/kooshapari/CodeProjects/Phenotype/repos/heliosApp/apps/runtime/tests/unit/lanes/watchdog/worktree_detector.test.ts</code></li><li><code>/Users/kooshapari/CodeProjects/Phenotype/repos/heliosApp/apps/runtime/tests/unit/lanes/watchdog/zellij_detector.test.ts</code></li><li><code>/Users/kooshapari/CodeProjects/Phenotype/repos/heliosApp/apps/runtime/tests/unit/lanes/watchdog/pty_detector.test.ts</code></li><li><code>/Users/kooshapari/CodeProjects/Phenotype/repos/heliosApp/apps/runtime/tests/unit/lanes/watchdog/resource_classifier.test.ts</code></li></ul></li><li>Parallel: Yes (after T001-T005 interfaces are stable).</li></ul><h2 id="test-strategy" tabindex="-1">Test Strategy <a class="header-anchor" href="#test-strategy" aria-label="Permalink to &quot;Test Strategy&quot;">​</a></h2><ul><li>Unit tests with mocked filesystem, process table, and zellij CLI.</li><li>False-positive rate validation with healthy system mocks.</li><li>Checkpoint crash recovery simulation.</li><li>Aim for &gt;=90% line coverage.</li></ul><h2 id="risks-mitigations" tabindex="-1">Risks &amp; Mitigations <a class="header-anchor" href="#risks-mitigations" aria-label="Permalink to &quot;Risks &amp; Mitigations&quot;">​</a></h2><ul><li>Risk: race condition between detection and lane creation causes false positive.</li><li>Mitigation: grace periods and two-cycle confirmation before reporting.</li><li>Risk: platform-specific process enumeration differs between macOS and Linux.</li><li>Mitigation: abstract process enumeration behind a platform adapter interface.</li></ul><h2 id="review-guidance" tabindex="-1">Review Guidance <a class="header-anchor" href="#review-guidance" aria-label="Permalink to &quot;Review Guidance&quot;">​</a></h2><ul><li>Confirm each detector correctly cross-references against the active lane/session registry.</li><li>Confirm transient state exclusion (cleaning, recovering) prevents false positives.</li><li>Confirm resource classifier risk levels match spec requirements.</li><li>Confirm checkpoint persistence handles corrupt files gracefully.</li><li>Confirm false-positive validation runs sufficient iterations.</li></ul><h2 id="activity-log" tabindex="-1">Activity Log <a class="header-anchor" href="#activity-log" aria-label="Permalink to &quot;Activity Log&quot;">​</a></h2><ul><li>2026-02-27T00:00:00Z -- system -- lane=planned -- Prompt created.</li><li>2026-03-01T13:29:37Z – claude-haiku – shell_pid=54633 – lane=doing – Assigned agent via workflow command</li><li>2026-03-01T13:32:23Z – claude-haiku – shell_pid=54633 – lane=done – Implemented watchdog scheduler and detectors</li></ul>',32)])])}const m=t(a,[["render",r]]);export{u as __pageData,m as default};
